import{z as l,x as d,o as t,c,q as o,j as i,D as e,d as E,s as r,S as B,b as s}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"软更新对照","description":"","frontmatter":{"title":"软更新对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/soft-updates.md","filePath":"cs/soft-updates.md","lastUpdated":1791063341000}'),p={name:"cs/soft-updates.md"};function A(f,a,u,D,m,h){const n=d("Mermaid");return t(),c("div",null,[a[2]||(a[2]=o('<h1 id="软更新对照" tabindex="-1">软更新对照 <a class="header-anchor" href="#软更新对照" aria-label="Permalink to &quot;软更新对照&quot;">​</a></h1><div class="epigraph"><p>软更新不写日志：它在内存里给缓冲更新排依赖，使落盘顺序永远保持「先指针后对象」或反过来的安全方向，崩溃后至多泄漏，不交叉指错。</p><footer>—— 据 Ganger, McKusick, Patt et al., Soft Updates: A Technique for Eliminating Most Synchronous Writes in the Fast Filesystem, ACM TOCS 2002</footer></div><p><a href="/cs/fs-snapshots">上一课</a>把一致切面交给 COW 根。<a href="/cs/ext4-journal">日志</a> 把更新抄到旁路。<a href="/cs/log-structured-fs">LFS</a> 把盘当成日志。FFS 还可以走第三条路：<strong>软更新</strong>。本课是对照，不是劝你在 Linux 上启用它——Linux 主线走的是日志与 COW。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无序写回时，目录项可能指向未初始化的 inode，或位图显示空闲但文件仍指向该块——fsck 必须修交叉。若每次元数据都同步，性能崩。<a href="/cs/fsync">fsync</a> 只等待一个文件。缺口：给脏缓冲加依赖边（「这块必须先于那块」），循环依赖则先回滚内存里的部分更新、写盘、再重新挂上。崩溃后文件系统总是一种可挂载的超集：可能有未回收的 inode/块，没有「已用对象指向垃圾」。</p><p><span class="marginnote">直觉类比：软更新不写「施工日志」，而是规定每片砖的粘贴顺序——任何时刻被打断，墙面最多少几块砖（泄漏），绝不会出现两片砖互相支撑的悬空结构（交叉指错）。fsck 只需回收没贴完的砖，不用修裂痕。</span></p><p><span class="marginnote">McKusick 在 BSD FFS 落地。依赖图的结点是缓冲，不是 POSIX 操作。与数据库 WAL 对照：这里没有 REDO 记录，只有写序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>creat</code>：先保证 inode 在盘上已分配且链接计数正确，再写目录项。<code>unlink</code>：先清目录项，再把 inode 计数与块释放排在后面。写回守护进程只选取依赖已满足的缓冲。与 JBD2：没有 journal inode，没有 commit 块；恢复靠后台 <code>fsck -p</code> 回收泄漏，通常很快，因为结构不坏。</p>',9)),(t(),i(B,null,{default:e(()=>[r(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22creat%2Funlink%22%5D%20--%3E%20DEP%5B%22%E7%BC%93%E5%86%B2%E4%BE%9D%E8%B5%96%E8%BE%B9%22%5D%0A%20%20DEP%20--%3E%20WB%5B%22%E5%8F%AA%E5%86%99%E5%B0%B1%E7%BB%AA%E7%BC%93%E5%86%B2%22%5D%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20LEAK%5B%22%E8%87%B3%E5%A4%9A%E6%B3%84%E6%BC%8F%22%5D%0A%20%20LEAK%20--%3E%20FSCK%5B%22%E5%90%8E%E5%8F%B0%E5%9B%9E%E6%94%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[E("软更新把「崩溃一致」定义成"),s("strong",null,"永不指向未初始化对象"),E("，把泄漏交给 fsck。这比全量扫描修交叉便宜，又比重做一份日志少一次写。它不给快照当原语，也不给端到端校验当提交点。教学价值：同一 POSIX 树，至少三种实现——日志、COW、依赖序。")],-1)),(t(),i(B,null,{default:e(()=>[r(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CR%5B%22creat%20%E5%BB%BA%E6%96%B0%E6%96%87%E4%BB%B6%22%5D%20--%3E%20C1%5B%22%E5%85%88%E5%86%99%20inode%20%E5%B9%B6%E8%90%BD%E7%9B%98%20%E9%93%BE%E6%8E%A5%E8%AE%A1%E6%95%B0%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E4%B9%8B%E5%90%8E%E6%89%8D%E5%85%81%E8%AE%B8%E5%86%99%E7%9B%AE%E5%BD%95%E9%A1%B9%E6%8C%87%E5%90%91%E5%AE%83%22%5D%0A%20%20C2%20--%3E%20S1%5B%22%E5%85%88%E5%AF%B9%E8%B1%A1%E5%90%8E%E6%8C%87%E9%92%88%3A%20%E7%9B%AE%E5%BD%95%E6%B0%B8%E4%B8%8D%E6%8C%87%E5%90%91%E6%9C%AA%E5%88%9D%E5%A7%8B%E5%8C%96%20inode%22%5D%0A%20%20UL%5B%22unlink%20%E5%88%A0%E6%96%87%E4%BB%B6%22%5D%20--%3E%20U1%5B%22%E5%85%88%E6%B8%85%E7%9B%AE%E5%BD%95%E9%A1%B9%22%5D%0A%20%20U1%20--%3E%20U2%5B%22inode%20%E8%AE%A1%E6%95%B0%E4%B8%8E%E5%9D%97%E9%87%8A%E6%94%BE%E6%8E%92%E5%88%B0%E5%90%8E%E9%9D%A2%22%5D%0A%20%20U2%20--%3E%20S2%5B%22%E5%85%88%E6%8C%87%E9%92%88%E5%90%8E%E5%AF%B9%E8%B1%A1%3A%20%E4%B8%8D%E4%BC%9A%E7%95%99%E4%B8%8B%E6%8C%87%E5%90%91%E5%B7%B2%E9%87%8A%E6%94%BE%E5%9D%97%E7%9A%84%E6%B4%BB%E7%9B%AE%E5%BD%95%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">这张图回答「为什么 creat 与 unlink 的安全顺序正好相反」：新建要防「指针先到、对象未生」，删除要防「对象先亡、指针还在」。同一套依赖图机制，在两种操作上给出方向相反的落盘序——这是软更新最值得记住的一处不对称。</span></p><p>不要把软更新写成编译课的指令调度：虽然都是依赖图，对象是磁盘缓冲。</p><p>实现上：循环依赖时要 rollback 内存中的指针再写盘，等于短暂违背「内存即真相」。BSD 的后台 fsck 专门回收泄漏，所以软更新把正确性定义成「可挂载超集」而不是「无泄漏」。 读法上只引用<a href="/cs/fs-snapshots">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">循环依赖为什么是难点：比如目录项 A 指向块 X，块 X 又承载 A 的元数据，两者谁都不能先安全落盘。软更新的解法是把内存里的部分改动临时回滚，让底层先写盘，再把回滚的改动挂回来——所以说「内存即真相」被短暂违背了。</span></p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>软更新对照</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BSD 与 Linux 的缓冲层代码对译。不保证 USB 拔出时依赖都已满足。下一课把「泄漏与交叉」收成工具：fsck 实际扫什么、日志/COW 之后它还剩什么工作。</p><p><span class="marginnote">术语翻译：「可挂载超集」翻译成人话——崩溃后的磁盘是一个结构合法、能直接挂载的文件系统，只是可能比崩溃前<strong>多</strong>一些没人引用的 inode 和块：只会多不会少。多出来的垃圾等后台 fsck 慢慢回收即可。</span></p><p>版本字段会变，课序钉的是机制对象「软更新对照」，不是某一主线内核的结构体名。 后课默认：原地 FS 可以用依赖序避免交叉。检查与修复程序如何走超级块、位图与目录，下一课 fsck。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>软更新用写序保证不交叉；崩溃至多泄漏。</li><li>对照日志与 COW：旁路抄写 vs 新根 vs 依赖图。</li><li>fsck 的剩余工作是下一课。</li><li>出处：Ganger, McKusick, Patt et al., TOCS 2002；McKusick, <em>The Design and Implementation of the FreeBSD Operating System</em>。</li></ul>',12))])}const k=l(p,[["render",A]]);export{S as __pageData,k as default};
